// Calendar Booking Configuration
// Choose ONE provider and configure below

export const calendarConfig = {
  // STEP 1: Choose your provider
  provider: 'calendly', // Options: 'calendly', 'cal', 'google'

  // STEP 2: Configure your chosen provider

  // CALENDLY (Recommended - Easiest)
  // Free: 1 event type | Paid: $10/mo
  // Setup: https://calendly.com → Create account → Create event type
  calendly: {
    username: 'admin-cirronyx',      // Replace with your Calendly username
    eventSlug: '30min',      // Replace with your event slug
    // Example URL: https://calendly.com/your-username/consultation
  },

  // CAL.COM (Open Source Alternative)  
  // Free: Unlimited events
  // Setup: https://cal.com → Create account → Create event type
  cal: {
    username: 'admin-cirronyx',      // Replace with your Cal.com username
    eventSlug: '30min',      // Replace with your event slug
    // Example URL: https://cal.com/your-username/consultation
  },

  // GOOGLE CALENDAR APPOINTMENT SCHEDULING
  // Requires Google Workspace
  // Setup: Google Calendar → Settings → Appointment schedules → Create
  google: {
    scheduleUrl: 'https://calendly.com/admin-cirronyx/30min',
  }
};

// Helper to get the calendar URL based on provider
export const getCalendarUrl = () => {
  const { provider, calendly, cal, google } = calendarConfig;

  switch (provider) {
    case 'calendly':
      return `https://calendly.com/${calendly.username}/${calendly.eventSlug}`;
    case 'cal':
      return `https://cal.com/${cal.username}/${cal.eventSlug}`;
    case 'google':
      return google.scheduleUrl;
    default:
      console.warn('No calendar provider configured');
      return '#';
  }
};

export default calendarConfig;
